=== FILE: apb_regs.v ===
`timescale 1ns/1ps
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements microarchitecture.md: zero wait states, no state machine,
// PSLVERR for unmapped (misaligned or >= 0x10) addresses.
module apb_regs #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam integer STRB_WIDTH = DATA_WIDTH / 8;

    // Access phase: the one cycle in which the response is sampled and a
    // write takes effect (pready is always high).
    wire apb_access;
    wire mapped;
    wire wr_en;
    wire rd_en;
    wire [1:0] idx;

    assign apb_access = psel & penable;
    assign mapped     = (paddr[1:0] == 2'b00) &&
                        (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    assign wr_en      = apb_access &  pwrite & mapped;
    assign rd_en      = apb_access & ~pwrite & mapped;
    assign idx        = paddr[3:2];

    // Register storage: separate flops.
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    // Byte write mask from the strobes.
    wire [DATA_WIDTH-1:0] wmask;
    genvar g;
    generate
        for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_wmask
            assign wmask[8*g +: 8] = {8{pstrb[g]}};
        end
    endgenerate

    // Selected register (read mux and write merge source).
    reg [DATA_WIDTH-1:0] sel_q;
    always @* begin
        case (idx)
            2'd0:    sel_q = reg0;
            2'd1:    sel_q = reg1;
            2'd2:    sel_q = reg2;
            2'd3:    sel_q = reg3;
            default: sel_q = reg0;
        endcase
    end

    // merge(old, data, strb): strobed bytes from pwdata, others kept.
    wire [DATA_WIDTH-1:0] merged;
    assign merged = (sel_q & ~wmask) | (pwdata & wmask);

    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
        end else if (wr_en && (idx == 2'd0)) begin
            reg0 <= merged;
        end
    end

    always @(posedge pclk) begin
        if (!presetn) begin
            reg1 <= {DATA_WIDTH{1'b0}};
        end else if (wr_en && (idx == 2'd1)) begin
            reg1 <= merged;
        end
    end

    always @(posedge pclk) begin
        if (!presetn) begin
            reg2 <= {DATA_WIDTH{1'b0}};
        end else if (wr_en && (idx == 2'd2)) begin
            reg2 <= merged;
        end
    end

    always @(posedge pclk) begin
        if (!presetn) begin
            reg3 <= {DATA_WIDTH{1'b0}};
        end else if (wr_en && (idx == 2'd3)) begin
            reg3 <= merged;
        end
    end

    // Responses.
    assign pready  = 1'b1;
    assign pslverr = apb_access & ~mapped;
    assign prdata  = rd_en ? sel_q : {DATA_WIDTH{1'b0}};

`ifdef FORMAL
    // Design-intent assertions (not proven: no formal_spec submitted).
    always @* begin
        assert (pready == 1'b1);
        if (!apb_access) begin
            assert (prdata == {DATA_WIDTH{1'b0}});
            assert (pslverr == 1'b0);
        end
        if (apb_access && !mapped) begin
            assert (prdata == {DATA_WIDTH{1'b0}});
            assert (pslverr == 1'b1);
        end
    end
`endif

endmodule
=== END FILE ===
