`timescale 1ns/1ps
// Self-checking directed testbench for apb_regs.
// Drives inputs after the falling edge, samples before the rising edge.
module apb_regs_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    apb_regs #(.ADDR_WIDTH(8), .DATA_WIDTH(32)) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    integer passed;
    integer failed;
    reg [8*64-1:0] nonce;
    reg [31:0] model [0:3];
    integer a;
    integer s;
    integer r;

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // Independent reference decode and byte merge.
    function tb_mapped;
        input [7:0] addr;
        begin
            tb_mapped = (addr[1:0] == 2'b00) && (addr < 8'h10);
        end
    endfunction

    function [31:0] tb_merge;
        input [31:0] old;
        input [31:0] data;
        input [3:0]  strb;
        reg   [31:0] res;
        integer b;
        begin
            res = old;
            for (b = 0; b < 4; b = b + 1) begin
                if (strb[b]) res[8*b +: 8] = data[8*b +: 8];
            end
            tb_merge = res;
        end
    endfunction

    task check_bit;
        input          got;
        input          exp;
        input [8*64-1:0] what;
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("%0s (paddr=0x%02h): got %b, expected %b at %0t",
                       what, paddr, got, exp, $time);
            end
        end
    endtask

    task check_word;
        input [31:0]     got;
        input [31:0]     exp;
        input [8*64-1:0] what;
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("%0s (paddr=0x%02h): got 0x%08h, expected 0x%08h at %0t",
                       what, paddr, got, exp, $time);
            end
        end
    endtask

    task check_quiet;
        input [8*64-1:0] what;
        begin
            check_word(prdata, 32'h0000_0000, what);
            check_bit(pslverr, 1'b0, what);
        end
    endtask

    task idle;
        input integer n;
        integer k;
        begin
            for (k = 0; k < n; k = k + 1) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = 1'b0;
                pwrite  = 1'b0;
                pstrb   = 4'h0;
                #1;
                check_quiet("idle: prdata/pslverr quiet");
            end
        end
    endtask

    task apb_write;
        input [7:0]  addr;
        input [31:0] data;
        input [3:0]  strb;
        reg exp_err;
        begin
            exp_err = !tb_mapped(addr);
            // Setup phase.
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = addr;
            pwdata  = data;
            pstrb   = strb;
            #1;
            check_quiet("write setup: quiet");
            // Access phase.
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_bit(pready, 1'b1, "write access: zero wait states");
            check_bit(pslverr, exp_err, "write access: pslverr policy");
            if (!exp_err) model[addr[3:2]] = tb_merge(model[addr[3:2]], data, strb);
        end
    endtask

    task apb_read;
        input [7:0] addr;
        reg        exp_err;
        reg [31:0] exp_data;
        begin
            exp_err  = !tb_mapped(addr);
            exp_data = exp_err ? 32'h0000_0000 : model[addr[3:2]];
            // Setup phase.
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = addr;
            pwdata  = 32'h0000_0000;
            pstrb   = 4'h0;
            #1;
            check_quiet("read setup: quiet");
            // Access phase.
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_bit(pready, 1'b1, "read access: zero wait states");
            check_bit(pslverr, exp_err, "read access: pslverr policy");
            check_word(prdata, exp_data, "read access: prdata");
        end
    endtask

    task do_reset;
        integer k;
        begin
            @(negedge pclk);
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            pstrb   = 4'h0;
            presetn = 1'b0;
            for (k = 0; k < 3; k = k + 1) begin
                #1;
                check_quiet("in reset: quiet");
                @(negedge pclk);
            end
            presetn = 1'b1;
            #1;
            check_quiet("after reset: quiet");
            for (k = 0; k < 4; k = k + 1) model[k] = 32'h0000_0000;
        end
    endtask

    initial begin
        passed  = 0;
        failed  = 0;
        nonce   = {8*64{1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {8*64{1'b0}};

        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'h00;
        pwdata  = 32'h0000_0000;
        pstrb   = 4'h0;
        for (r = 0; r < 4; r = r + 1) model[r] = 32'h0000_0000;

        // 1. Reset and reset values.
        do_reset;
        idle(2);
        for (r = 0; r < 4; r = r + 1) begin
            apb_read({4'h0, r[1:0], 2'b00});
            idle(1);
        end

        // 2. Full-word write then read of every register, back to back.
        apb_write(8'h00, 32'hA5A5_0001, 4'hF);
        apb_write(8'h04, 32'h5A5A_0002, 4'hF);
        apb_write(8'h08, 32'hDEAD_BEEF, 4'hF);
        apb_write(8'h0C, 32'hCAFE_F00D, 4'hF);
        apb_read(8'h00);
        apb_read(8'h04);
        apb_read(8'h08);
        apb_read(8'h0C);
        idle(3);

        // 3. Every strobe pattern, including none, each followed by a read.
        for (s = 0; s < 16; s = s + 1) begin
            apb_write({4'h0, s[1:0], 2'b00},
                      {s[3:0], 4'h1, s[3:0], 4'h2, s[3:0], 4'h3, s[3:0], 4'h4} ^ 32'hF0F0_0F0F,
                      s[3:0]);
            apb_read({4'h0, s[1:0], 2'b00});
            if (s[0]) idle(1);
        end

        // 4. Zero-strobe write changes nothing and completes without error.
        apb_write(8'h04, 32'hFFFF_FFFF, 4'h0);
        apb_read(8'h04);
        idle(2);

        // 5. Every address in the slot: policy, read-back, and no aliasing.
        for (a = 0; a < 256; a = a + 1) begin
            apb_write(a[7:0], {a[7:0], ~a[7:0], a[7:0] ^ 8'h5A, 8'hC3}, 4'hF);
            apb_read(a[7:0]);
            apb_read({4'h0, a[3:2], 2'b00});
            if (a[2:0] == 3'b111) idle(1);
        end
        for (r = 0; r < 4; r = r + 1) apb_read({4'h0, r[1:0], 2'b00});
        idle(2);

        // 6. Reset again with non-zero contents.
        apb_write(8'h00, 32'h1234_5678, 4'hF);
        apb_write(8'h0C, 32'h8765_4321, 4'hF);
        do_reset;
        idle(1);
        for (r = 0; r < 4; r = r + 1) apb_read({4'h0, r[1:0], 2'b00});
        idle(2);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
